def areSequencesSimilar(a, b, pairs):
    if len(a) != len(b):
        return False
    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for x, y in pairs:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
    for u, v in zip(a, b):
        if u != v and find(u) != find(v):
            return False
    return True
